-- Explicit targets include anonymous controls that cannot be found by global names.
local function SkinRegisteredTarget(frame, kind, options)
    local scope = options.scope or APR:GetSkinScope(frame)
    if APR.ApplyNativeTheme and APR.GetThemeStyle and APR:GetThemeStyle(scope) == "modern" then
        APR:ApplyNativeTheme(frame, kind, options)
        if kind == "statusbar" then
            if E.media and E.media.normTex then frame:SetStatusBarTexture(E.media.normTex) end
            APR:ApplyStatusBarColor(frame)
        end
        MarkSkinned(frame)
        return
    end
    if kind == "flatButton" then
        -- MDI actions and sort headings keep their compact, borderless hit area.
        MarkSkinned(frame)
    elseif kind == "button" then
        SkinButton(frame)
    elseif kind == "arrow" and not IsSkinned(frame) and S.HandleNextPrevButton then
        -- Some APR arrow controls still carry their own text label (tooltip text or older templates).
        -- ElvUI's HandleNextPrevButton strips text strings and can crash if a FontString exists without a font.
        local currentText = frame.GetText and frame:GetText()
        if currentText and currentText ~= "" then
            if S.HandleButton then
                S:HandleButton(frame)
            end
            MarkSkinned(frame)
            return
        end
        local width, height = frame:GetSize()
        S:HandleNextPrevButton(frame, options.direction, nil, nil, true, nil, width)
        frame:SetSize(width, height)
        MarkSkinned(frame)
    elseif kind == "scrollbar" and not IsSkinned(frame) and S.HandleScrollBar then
        S:HandleScrollBar(frame)
        MarkSkinned(frame)
    elseif kind == "close" then
        local width, height = frame:GetSize()
        SkinCloseButton(frame)
        frame:SetSize(width, height)
    elseif kind == "icon" and not IsSkinned(frame) and S.HandleIcon then
        -- Style the texture only; never strip or rewrite secure item buttons.
        S:HandleIcon(options.texture, true)
        MarkSkinned(frame)
    elseif (kind == "window" or kind == "borderedPanel" or kind == "panel" or kind == "row" or kind == "divider") and not IsSkinned(frame) then
        if frame.SetTemplate then frame:SetTemplate("Transparent") end
        MarkSkinned(frame)
    elseif kind == "header" then
        SkinOTHeader(frame)
    elseif kind == "headerButton" then
        if options.close then SkinCloseButton(frame) else SkinSecondaryMinimizeButton(frame, options.parent) end
    elseif kind == "statusbar" then
        if E.media and E.media.normTex then frame:SetStatusBarTexture(E.media.normTex) end
        APR:ApplyStatusBarColor(frame)
    elseif kind == "settings" then
        SkinSettingsIconButton(frame)
    elseif kind == "editbox" and not IsSkinned(frame) and S.HandleEditBox then
        if options.themeSurface and frame.SetBackdrop then frame:SetBackdrop(nil) end
        S:HandleEditBox(frame)
        MarkSkinned(frame)
    end
end--[[APR_DIAG]]; SkinRegisteredTarget = APRTrace("APR-Core/integrations/ElvUISkin.lua:264:SkinRegisteredTarget#17", SkinRegisteredTarget)--[[/APR_DIAG]]

local hooksInstalled = false
function APR.ElvUISkin:OnEnable()
    if not IsElvUISkinEnabled() then return end

    APR:RegisterSkinProvider("ElvUI", SkinRegisteredTarget, IsElvUISkinEnabled)
    APR:RegisterStaticSkinTargets()
    if not hooksInstalled then
        HookDynamicFrames()
        if E.UpdateMedia then
            hooksecurefunc(E, "UpdateMedia", --[[APR_DIAG]]APRTrace("APR-Core/integrations/ElvUISkin.lua:334:callback#19", --[[/APR_DIAG]]function() APR:RefreshRegisteredSkins() end--[[APR_DIAG]])--[[/APR_DIAG]])
        end
        hooksInstalled = true
    end
    UpdateSnappedBackdrops()
end--[[APR_DIAG]]; APR.ElvUISkin.OnEnable = APRTrace("APR-Core/integrations/ElvUISkin.lua:326:APR.ElvUISkin:OnEnable#18", APR.ElvUISkin.OnEnable)--[[/APR_DIAG]]

--- Re-apply skins (called when the setting is toggled on)
function APR.ElvUISkin:ApplySkins()
    if not IsElvUISkinEnabled() then return end

    APR:RefreshRegisteredSkins()
    if InCombatLockdown() then return end
    APR:RegisterStaticSkinTargets()
    UpdateSnappedBackdrops()
end--[[APR_DIAG]]; APR.ElvUISkin.ApplySkins = APRTrace("APR-Core/integrations/ElvUISkin.lua:342:APR.ElvUISkin:ApplySkins#20", APR.ElvUISkin.ApplySkins)--[[/APR_DIAG]]
